df["objects"] = df["objects"].apply(json.dumps)

# Template for statistic:
_CACHE = {}

def get_indices(df):
    if "idx" not in _CACHE:
        # compute once
        unique = df[["objects", "heard", "probe"]].drop_duplicates()
        matching_keys = set()
        for _, r in unique.iterrows():
            if pd.notna(r["heard"]):
                objs = json.loads(r["objects"])
                h = int(r["heard"])
                p = int(r["probe"])
                if all(o[h] == 1 for o in objs):
                    if sum(1 for o in objs if o == objs[p]) == 1:
                        distractors = [o for i, o in enumerate(objs) if i != p]
                        if len(set(tuple(o) for o in distractors)) == 1:
                            if sum(objs[p]) <= sum(distractors[0]):
                                matching_keys.add((r["objects"], r["heard"], r["probe"]))
        keys = list(zip(df["objects"], df["heard"], df["probe"]))
        _CACHE["idx"] = np.where([k in matching_keys for k in keys])[0]
    return _CACHE["idx"]

